        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, for those with any. */
    @Transactional(readOnly = true)
    public List<Summary> summaries(String sheetId) {
        Map<Long, List<Statement>> byPerson = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            byPerson.computeIfAbsent(s.getPersonId(), id -> new ArrayList<>()).add(s);
        }
        return byPerson.entrySet().stream().map(e -> summaryOf(e.getKey(), e.getValue())).toList();
    }

    @Transactional
    public Taken take(String sheetId, String user, Long personId) {
        // Lock the sheet so the claims and rates read are not changed while the statement is taken.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        boolean fixed = false;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!claim.getStatus().counts(person.isHeld())) {
        if (claim.isStated()) return claim.getStatedDue();
        return dueOf(sheetId, person, claim);
    }

    /**
     * A claim's due now: its figure, with the late charge on top while it is overdue; null when it
     * has none. A statement binds the figure, never the charge.
     */
    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
        BigDecimal figure = figureOf(sheetId, person, claim);
        if (claim.getSettledDue() != null) return figure;
        return LateCharge.withCharge(claim, figure, settings.terms(sheetId), sheets.today(sheetId),
                settings.latePct(sheetId));
    }

    /**
     * A claim's live due: its amount times its person's grade rate on its date, rounded half to even
     * to cents, and at least the sheet's floor; null with no rate.
     */
    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
        BigDecimal floor = settings.floor(sheetId);
        return rates.on(sheetId, person.getGrade(), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
                .map(due -> due.max(floor))
                .orElse(null);
    }

    private void record(String event, String sheetId, String user, Person person, Claim claim) {
        record(event, sheetId, user, person, claim, claim.getNumber(), "");
    }

    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
    private void record(String event, String sheetId, String user, Person person, Claim claim, Long number,
            String extra) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "") + extra);
    }

    /** Refuse a clerk's settling of a claim whose due is above the clerk limit; a due of n/a is within any. */
    private void refuseIfOverClerkLimit(String sheetId, String user, BigDecimal due) {
        if (settings.roleOf(sheetId, user) == Role.STEWARD) return;
        BigDecimal limit = settings.clerkLimit(sheetId);
        if (limit != null && due != null && due.compareTo(limit) > 0) throw new ClaimOverClerkLimitException();
    }

    /** Refuse a change to a claim dated inside a closed period; the caller holds the sheet's lock. */
    private void refuseIfClosed(String sheetId, LocalDate date) {
        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
    }

