      const grade = grades.get(c.personId);
      if (period === null || grade === undefined) continue;
      by.set(period.id, (by.get(period.id) ?? 0) + (claimDueCents(c, this.ratesOf(grade), cents(this.session.floor()), this.session.late()) ?? 0));
